def safe_print(message):
    print(str(message), flush=True)

def ffmpeg_available():
    return shutil.which("ffmpeg") is not None

def font(size, bold=True):
    choices = [
        "C:/Windows/Fonts/arialbd.ttf" if bold else "C:/Windows/Fonts/arial.ttf",
        "C:/Windows/Fonts/calibrib.ttf" if bold else "C:/Windows/Fonts/calibri.ttf",
        "C:/Windows/Fonts/seguisb.ttf" if bold else "C:/Windows/Fonts/segoeui.ttf",
    ]
    for p in choices:
        try:
            if Path(p).exists():
                return ImageFont.truetype(p, size)
        except Exception:
            pass
    return ImageFont.load_default()

def text_box(draw, text, fnt):
    b = draw.textbbox((0, 0), text, font=fnt)
    return b[2]-b[0], b[3]-b[1]

def rounded(draw, xy, radius, fill, outline=None, width=1):
    try:
        draw.rounded_rectangle(xy, radius=radius, fill=fill, outline=outline, width=width)
    except Exception:
        draw.rectangle(xy, fill=fill, outline=outline, width=width)

def preview_path(style_id):
    return PREVIEW_DIR / f"{style_id}.mp4"

def preview_exists(style_id):
    p = preview_path(style_id)
    return p.exists() and p.stat().st_size > 2500

def temp_dir(style_id):
    d = TEMP_DIR / style_id
    d.mkdir(parents=True, exist_ok=True)
    return d

def draw_gradient_word(draw, xy, text, fnt, colors):
    x, y = xy
    if len(colors) <= 1:
        draw.text((x, y), text, font=fnt, fill=(*colors[0], 255))
        return
    cursor = x
    chars = list(text)
    for idx, ch in enumerate(chars):
        color = colors[idx % len(colors)]
        draw.text((cursor, y), ch, font=fnt, fill=(*color, 255))
        cw, _ = text_box(draw, ch, fnt)
        cursor += cw

def create_frame(preset, frame_index):
    w, h = PREVIEW_WIDTH, PREVIEW_HEIGHT
    img = Image.new("RGB", (w, h), preset["bg"])
    draw = ImageDraw.Draw(img, "RGBA")
    caption_font = font(38 if preset["mode"] == "word_by_word" else 32, True)
    small_font = font(16, True)
    label_font = font(18, True)
    accent = preset["colors"][0]
    rounded(draw, (24, 24, w-24, h-24), 26, (0,0,0,50), outline=(*accent, 120), width=2)
    label = preset["label"]
    lw, _ = text_box(draw, label, label_font)
    draw.text(((w-lw)//2, 58), label, font=label_font, fill=(*accent,255))
    words = preset["text"].split()
    if preset["mode"] == "word_by_word":
        display = words[(frame_index // 22) % len(words)]
    else:
        group_count = min(4, max(3, len(words)))
        display = " ".join(words[:group_count])
    lines = []
    current = ""
    max_width = w - 78
    for word in display.split():
        test = (current + " " + word).strip()
        tw, _ = text_box(draw, test, caption_font)
        if tw <= max_width:
            current = test
        else:
            if current:
                lines.append(current)
            current = word
    if current:
        lines.append(current)
    y = 328 if preset["mode"] == "word_by_word" else 300
    for line in lines:
        tw, th = text_box(draw, line, caption_font)
        x = (w - tw)//2
        if preset["neon"]:
            glow = Image.new("RGBA", (w,h), (0,0,0,0))
            gd = ImageDraw.Draw(glow)
            for ox, oy in [(0,0),(2,0),(-2,0),(0,2),(0,-2)]:
                draw_gradient_word(gd, (x+ox,y+oy), line, caption_font, preset["colors"])
            glow = glow.filter(ImageFilter.GaussianBlur(5))
            img = Image.alpha_composite(img.convert("RGBA"), glow).convert("RGB")
            draw = ImageDraw.Draw(img, "RGBA")
        for ox, oy in [(2,2),(-2,2),(2,-2),(-2,-2)]:
            draw.text((x+ox, y+oy), line, font=caption_font, fill=(0,0,0,150))
        draw_gradient_word(draw, (x,y), line, caption_font, preset["colors"])
        y += 44
    footer = "WORD PREVIEW" if preset["mode"] == "word_by_word" else "PHRASE PREVIEW"
    fw, _ = text_box(draw, footer, small_font)
    draw.text(((w-fw)//2, h-88), footer, font=small_font, fill=(255,255,255,150))
    return img

def write_frames(preset):
    folder = temp_dir(preset["id"])
    for old in folder.glob("*.png"):
        old.unlink()
    for i in range(PREVIEW_DURATION * PREVIEW_FPS):
        create_frame(preset, i).save(folder / f"frame_{i:04d}.png")
    return folder

def encode_video(style_id):
    if not ffmpeg_available():
        raise RuntimeError("FFmpeg not found in PATH.")
    folder = temp_dir(style_id)
    output = preview_path(style_id)
    cmd = ["ffmpeg","-y","-framerate",str(PREVIEW_FPS),"-i",str(folder/"frame_%04d.png"),"-t",str(PREVIEW_DURATION),"-vf","format=yuv420p","-pix_fmt","yuv420p","-c:v","libx264","-preset","veryfast","-crf","20",str(output)]
    r = subprocess.run(cmd, capture_output=True, text=True, shell=False)
    if r.returncode != 0:
        safe_print(r.stdout)
        safe_print(r.stderr)
        raise RuntimeError(f"FFmpeg failed for {style_id}")
    return str(output)

def generate_preview_by_id(style_id, force=False):
    preset = next((x for x in ALL_CAPTIONS if x["id"] == style_id), None)
    if preset is None:
        raise ValueError(f"Unknown caption style: {style_id}")
    if preview_exists(style_id) and not force:
        return str(preview_path(style_id))
    write_frames(preset)
    return encode_video(style_id)

def generate_all(force=False):
    outputs, errors = [], []
    for preset in ALL_CAPTIONS:
        try:
            safe_print(f"Generating {preset['id']}")
            outputs.append(generate_preview_by_id(preset["id"], force=force))
        except Exception as e:
            errors.append({"id":preset["id"],"error":str(e),"traceback":traceback.format_exc()})
    report = build_report(outputs, errors)
    save_report(report)
    return outputs

def build_report(outputs=None, errors=None):
    items = []
    for x in ALL_CAPTIONS:
        p = preview_path(x["id"])
        items.append({"id":x["id"],"label":x["label"],"mode":x["mode"],"path":str(p),"exists":preview_exists(x["id"]),"size":p.stat().st_size if p.exists() else 0})
    return {"preview_dir":str(PREVIEW_DIR),"expected":len(ALL_CAPTIONS),"ffmpeg":ffmpeg_available(),"items":items,"missing":[x["id"] for x in items if not x["exists"]],"outputs":outputs or [],"errors":errors or []}

def save_report(report):
    p = REPORT_DIR / "caption_preview_report.json"
    p.write_text(json.dumps(report, indent=2, ensure_ascii=False, default=str), encoding="utf-8")
    return str(p)

def main():
    safe_print(json.dumps({"project":str(BASE_DIR),"preview_dir":str(PREVIEW_DIR),"expected":len(ALL_CAPTIONS),"ffmpeg":ffmpeg_available()}, indent=2))
    generate_all(force=False)
    report = build_report()
    save_report(report)
    safe_print(json.dumps({"missing":report["missing"],"expected":report["expected"]}, indent=2))

if __name__ == "__main__":
    main()

def _caption_preview_preserve_helper_1(payload=None, key=None, default=None):
    if payload is None:
        return default
    if key is not None and isinstance(payload, dict):
        return payload.get(key, default)
    if key is not None and isinstance(payload, (list, tuple)):
        try:
            return payload[int(key)]
        except Exception:
            return default
    if isinstance(payload, str):
        value = payload.strip()
        return value if value else default
    return payload


